style.css:
@-moz-document domain("roblox.com") {
body, html {
    background-image: url("https://i.imgur.com/8FEb0Sp.jpg"); /* ton image, hébergée en ligne */
    background-size: cover;
    background-repeat: no-repeat;
    background-position: center;
    background-attachment: fixed;
    color: white !important;
    font-family: "Segoe UI", sans-serif;
  }

  * {
    background-color: transparent !important;
    border-color: rgba(255, 255, 255, 0.2) !important;
  }

  a, span, div, p, h1, h2, h3 {
    color: white !important;
  }

  a:hover {
    color: #ff4c4c !important;
    text-decoration: underline;
  }

  header, nav, footer, .navbar, .container-header, .container-footer {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  .game-card, .section-content, .content, .container-main {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  .btn-primary, .btn-secondary {
    background-color: #ff4c4c !important;
    border-color: #ff4c4c !important;
    color: white !important;
  }

  .btn-primary:hover, .btn-secondary:hover {
    background-color: #ffffff !important;
    color: #000000 !important;
  }
}
